// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.File;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * End-to-end guards for value-dependent packed recipes: concurrent planning of two constants of one parameterized
 * family must keep the in-domain constant's rows even though the out-of-domain one is proven empty, and planning in a
 * dirty transaction (no range provider) must never reuse a committed-data range proof.
 */
class LmdbPackedFamilyFlightIsolationTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI A = VF.createIRI("urn:a");
	private static final IRI B = VF.createIRI("urn:b");
	private static final IRI C = VF.createIRI("urn:c");

	@Test
	void concurrentFamilyPlanningMustNotShareEmptyProof(@TempDir File dataDir) throws Exception {
		SailRepository repository = repository(dataDir);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try (RepositoryConnection loader = repository.getConnection()) {
			loader.add(A, P, VF.createLiteral("7", XSD.INTEGER));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();
			int wrong = 0;
			int iterations = 40;
			for (int i = 0; i < iterations; i++) {
				String variable = "s" + i;
				String inDomain = "SELECT ?" + variable + " WHERE { ?" + variable + " <urn:p> 7 }";
				String outOfDomain = "SELECT ?" + variable + " WHERE { ?" + variable + " <urn:p> 9 }";
				CyclicBarrier barrier = new CyclicBarrier(2);
				Future<Set<String>> empty = executor.submit(() -> {
					try (RepositoryConnection connection = repository.getConnection()) {
						barrier.await();
						return rows(connection, outOfDomain, variable);
					}
				});
				Future<Set<String>> present = executor.submit(() -> {
					try (RepositoryConnection connection = repository.getConnection()) {
						barrier.await();
						return rows(connection, inDomain, variable);
					}
				});
				assertEquals(Set.of(), empty.get(), "out-of-domain constant");
				if (!Set.of("urn:a").equals(present.get())) {
					wrong++;
				}
			}
			assertEquals(0, wrong, "in-domain constant lost its row in " + wrong + " of " + iterations + " races");
		} finally {
			executor.shutdownNow();
			repository.shutDown();
		}
	}

	@Test
	void uncommittedOverlayMustSeeOwnValueEqualTerm(@TempDir File dataDir) {
		String query = "SELECT ?s WHERE { ?s <urn:p> ?o FILTER(?o = 5) }";
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, VF.createLiteral("6", XSD.INTEGER));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();
			assertEquals(Set.of("urn:a"), rows(connection, query, "s"));
			assertEquals(Set.of("urn:a"), rows(connection, query, "s"));

			connection.begin();
			connection.add(C, P, VF.createLiteral("5", XSD.INT));
			Set<String> inTxn = rows(connection, query, "s");
			connection.rollback();

			assertEquals(Set.of("urn:a", "urn:c"), inTxn, "uncommitted value-equal term must be visible");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void dirtyTransactionMustNotReuseCommittedRangeProof(@TempDir File dataDir) {
		String query = "SELECT ?s WHERE { ?s <urn:p> ?o FILTER(?o = 9) }";
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("7", XSD.INTEGER));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();
			assertEquals(Set.of(), rows(connection, query, "s"), "9 is outside the committed range");
			assertEquals(Set.of(), rows(connection, query, "s"));

			connection.begin();
			connection.add(B, P, VF.createLiteral("9", XSD.INTEGER));
			Set<String> inTxn = rows(connection, query, "s");
			connection.rollback();

			assertEquals(Set.of("urn:b"), inTxn,
					"a dirty transaction must see its own row although committed data proved the constant empty");
		} finally {
			repository.shutDown();
		}
	}

	private static SailRepository repository(File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		return repository;
	}

	private static Set<String> rows(RepositoryConnection connection, String query, String... names) {
		Set<String> rows = new TreeSet<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			for (BindingSet bindingSet : result) {
				StringBuilder row = new StringBuilder();
				for (int index = 0; index < names.length; index++) {
					if (index > 0) {
						row.append('|');
					}
					row.append(bindingSet.getValue(names[index]) == null ? "UNBOUND"
							: bindingSet.getValue(names[index]).stringValue());
				}
				rows.add(row.toString());
			}
		}
		return rows;
	}
}
